set -euo pipefail
FILE="html/war-rooms/construct-war/construction-strategist.html"

cat > /tmp/_construction_patch.py << 'PYEOF_INNER'
import sys
path = sys.argv[1]
with open(path) as fh:
    content = fh.read()

old_func = 'async function runConstructionBNCAFromRelay() {\n  if (!warRoomRelay) { runConstructionBNCA(); return; }\n \n  const out = document.getElementById(\'bncaOutput\');\n  const nodeEl = document.getElementById(\'currentNode\');\n  const engines = warRoomRelay.engines || {};\n  const snap = warRoomRelay.snapshot || {};\n \n  conXPResetExplain();\n  nodeEl.textContent = \'Synthesizing War Room relay via Groq...\';\n  out.classList.add(\'streaming\');\n  out.style.color = \'var(--text)\';\n  out.style.fontStyle = \'normal\';\n  out.textContent = \'▌\';\n \n  const ctx = `\nDOCUMENT TYPE: ${warRoomRelay.docType||\'Unknown\'}\nRISK SCORE: ${snap.risk||\'—\'}\nFINANCIAL EXPOSURE: ${snap.exposure||\'—\'}\nENGINE 01 — DOCUMENT INTEL: ${engines.e1||\'\'}\nENGINE 03 — FINANCIAL: ${engines.e3||\'\'}\nENGINE 04 — LEGAL: ${engines.e4||\'\'}\nENGINE 05 — COMPLIANCE: ${engines.e5||\'\'}\nENGINE 06 — BNCA EXEC: ${engines.e6||\'\'}\nPROJECT PHASE STATUS:\n${phaseSnapshotToText(getPhaseSnapshot())}\n  `.trim();\n \n  const sys = `You are a Construction Strategist AI. Synthesize war room engine data into a complete executive intelligence package. Be specific, dollar-quantified, and action-oriented.`;\n  const usr = `War Room Data:\\n${ctx}\\n\\nGenerate:\\n\\nCONTROLLER PRIORITY ACTIONS (4 actions, numbered, dollar-quantified, owner assigned, deadline):\\n\\nAPP ROUTING GUIDANCE (for each Construction Suite app — AuditOps, Financial, Legal, Compliance — give 2-3 sentences of specific step-by-step instruction on what tab to open, what data to enter, and what output to produce for THIS specific document and issue):\\n\\nBNCA — BEST NEXT COURSE OF ACTION (one paragraph, most important 72-hour action sequence):\\n\\nESCALATION TRIGGER (condition for immediate executive involvement):\\n\\nAfter the brief above, on a new line output exactly ===JSON=== followed by a single JSON object (no markdown fences) with this exact shape:\\n{"confidence":0-100,"dataSources":[{"name":"...","weight":"HIGH|MED|LOW"}],"reasoning":[{"key":"...","val":"..."}],"recommendedActions":[{"text":"...","owner":"..."}],"noActionRevLoss":"$amount","actionRevLoss":"$amount","recoveryTime":"e.g. 30 Days"}`;\n \n  try {\n    const res = await fetch(\'/api/war-room/stream\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({\n        model: \'openai/gpt-oss-120b\',\n        max_tokens: 1200,\n        temperature: 0.4,\n        stream: true,\n        messages: [{ role: \'system\', content: sys }, { role: \'user\', content: usr }]\n      })\n    });\n \n    if (!res.ok) {\n      const err = await res.json().catch(() => ({}));\n      out.textContent = \'[Groq Error] \' + (err.error?.message || res.statusText);\n      out.classList.remove(\'streaming\');\n      return;\n    }\n \n    const reader = res.body.getReader();\n    const dec = new TextDecoder();\n    let full = \'\';\n    out.textContent = \'\';\n \n    while (true) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      const chunk = dec.decode(value);\n      for (const line of chunk.split(\'\\n\')) {\n        if (!line.startsWith(\'data: \')) continue;\n        const data = line.slice(6).trim();\n        if (data === \'[DONE]\') break;\n        try {\n          const delta = JSON.parse(data).choices?.[0]?.delta?.content || \'\';\n          full += delta;\n          out.textContent = full + \'▌\';\n        } catch {}\n      }\n    }\n \n    out.textContent = full;\n    const {brief: conBrief, obj: conObj} = conXPParseExplain(full);\n    if(conBrief) out.textContent = conBrief;\n    conXPRenderExplain(conObj);\n    lastConObj = conObj;\n    out.classList.remove(\'streaming\');\n    nodeEl.textContent = `BNCA complete — War Room relay synthesized · ${new Date().toLocaleTimeString()}`;\n \n    // Store for executive portal (also escalates to Sentinel Center)\n    storeStrategistRelay(full, conObj);\n \n    // Update escalate bar\n    const sub = document.getElementById(\'escalBarSub\');\n    if (sub) sub.textContent = \'BNCA synthesis complete — ready to escalate to Executive Portal.\';\n\n    // AUTO-ESCALATE ON THRESHOLD BREACH — explicit override, 2026-08-01.\n    // This reverses the prior human-in-the-loop default (see git history /\n    // construction-war-room.html for the same disabled-by-design comment).\n    // Fires only when BNCA\'s own risk score crosses the existing CRIT\n    // threshold used elsewhere in this file (riskToSeverity >= 75) — reusing\n    // the established scale rather than inventing a new dollar cutoff.\n    // Any lower severity still waits for the manual "→ ESCALATE TO\n    // EXECUTIVE" click as before.\n    const autoRiskNum = parseRiskToNumber(warRoomRelay?.snapshot?.risk);\n    if (riskToSeverity(autoRiskNum) === \'CRIT\') {\n      if (sub) sub.textContent = `CRIT risk (${autoRiskNum}) — auto-escalating to Executive Portal…`;\n      nodeEl.textContent = `Threshold breach (CRIT, ${autoRiskNum}) — auto-escalating…`;\n      setTimeout(() => escalateToExecutive(), 1200);\n    }\n \n  } catch(e) {\n    out.textContent = \'[Error] \' + e.message;\n    out.classList.remove(\'streaming\');\n  }\n}'
new_func = 'async function runConstructionBNCAFromRelay() {\n  if (!warRoomRelay) { runConstructionBNCA(); return; }\n \n  const out = document.getElementById(\'bncaOutput\');\n  const nodeEl = document.getElementById(\'currentNode\');\n  const engines = warRoomRelay.engines || {};\n  const snap = warRoomRelay.snapshot || {};\n \n  conXPResetExplain();\n  nodeEl.textContent = \'Synthesizing War Room relay via Groq...\';\n  out.classList.add(\'streaming\');\n  out.style.color = \'var(--text)\';\n  out.style.fontStyle = \'normal\';\n  out.textContent = \'▌\';\n \n  const ctx = `\nDOCUMENT TYPE: ${warRoomRelay.docType||\'Unknown\'}\nRISK SCORE: ${snap.risk||\'—\'}\nFINANCIAL EXPOSURE: ${snap.exposure||\'—\'}\nENGINE 01 — DOCUMENT INTEL: ${engines.e1||\'\'}\nENGINE 03 — FINANCIAL: ${engines.e3||\'\'}\nENGINE 04 — LEGAL: ${engines.e4||\'\'}\nENGINE 05 — COMPLIANCE: ${engines.e5||\'\'}\nENGINE 06 — BNCA EXEC: ${engines.e6||\'\'}\nPROJECT PHASE STATUS:\n${phaseSnapshotToText(getPhaseSnapshot())}\n  `.trim();\n \n  const sys = `You are a Construction Strategist AI. Synthesize war room engine data into a complete executive intelligence package. Be specific, dollar-quantified, and action-oriented.`;\n  const usr = `War Room Data:\\n${ctx}\\n\\nGenerate:\\n\\nCONTROLLER PRIORITY ACTIONS (4 actions, numbered, dollar-quantified, owner assigned, deadline):\\n\\nAPP ROUTING GUIDANCE (for each Construction Suite app — AuditOps, Financial, Legal, Compliance — give 2-3 sentences of specific step-by-step instruction on what tab to open, what data to enter, and what output to produce for THIS specific document and issue):\\n\\nBNCA — BEST NEXT COURSE OF ACTION (one paragraph, most important 72-hour action sequence):\\n\\nESCALATION TRIGGER (condition for immediate executive involvement):\\n\\nAfter the brief above, on a new line output exactly ===JSON=== followed by a single JSON object (no markdown fences) with this exact shape:\\n{"confidence":0-100,"dataSources":[{"name":"...","weight":"HIGH|MED|LOW"}],"reasoning":[{"key":"...","val":"..."}],"recommendedActions":[{"text":"...","owner":"..."}],"noActionRevLoss":"$amount","actionRevLoss":"$amount","recoveryTime":"e.g. 30 Days"}`;\n \n  const ctrl = new AbortController();\n  const streamTimeoutId = setTimeout(() => ctrl.abort(), 30000); // hard ceiling so a hung connection degrades to the fallback brief instead of outliving the demo harness\'s step timeout\n  try {\n    const res = await fetch(\'/api/war-room/stream\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({\n        model: \'openai/gpt-oss-120b\',\n        max_tokens: 1200,\n        temperature: 0.4,\n        stream: true,\n        messages: [{ role: \'system\', content: sys }, { role: \'user\', content: usr }]\n      }),\n      signal: ctrl.signal\n    });\n \n    if (!res.ok) {\n      const err = await res.json().catch(() => ({}));\n      throw new Error(err.error?.message || res.statusText || (\'API returned \' + res.status));\n    }\n \n    const reader = res.body.getReader();\n    const dec = new TextDecoder();\n    let full = \'\';\n    out.textContent = \'\';\n \n    while (true) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      const chunk = dec.decode(value);\n      for (const line of chunk.split(\'\\n\')) {\n        if (!line.startsWith(\'data: \')) continue;\n        const data = line.slice(6).trim();\n        if (data === \'[DONE]\') break;\n        try {\n          const delta = JSON.parse(data).choices?.[0]?.delta?.content || \'\';\n          full += delta;\n          out.textContent = full + \'▌\';\n        } catch {}\n      }\n    }\n \n    out.textContent = full;\n    const {brief: conBrief, obj: conObj} = conXPParseExplain(full);\n    if(conBrief) out.textContent = conBrief;\n    conXPRenderExplain(conObj);\n    lastConObj = conObj;\n    out.classList.remove(\'streaming\');\n    nodeEl.textContent = `BNCA complete — War Room relay synthesized · ${new Date().toLocaleTimeString()}`;\n \n    // Store for executive portal (also escalates to Sentinel Center)\n    storeStrategistRelay(full, conObj);\n \n    // Update escalate bar\n    const sub = document.getElementById(\'escalBarSub\');\n    if (sub) sub.textContent = \'BNCA synthesis complete — ready to escalate to Executive Portal.\';\n\n    // AUTO-ESCALATE ON THRESHOLD BREACH — explicit override, 2026-08-01.\n    // This reverses the prior human-in-the-loop default (see git history /\n    // construction-war-room.html for the same disabled-by-design comment).\n    // Fires only when BNCA\'s own risk score crosses the existing CRIT\n    // threshold used elsewhere in this file (riskToSeverity >= 75) — reusing\n    // the established scale rather than inventing a new dollar cutoff.\n    // Any lower severity still waits for the manual "→ ESCALATE TO\n    // EXECUTIVE" click as before.\n    const autoRiskNum = parseRiskToNumber(warRoomRelay?.snapshot?.risk);\n    if (riskToSeverity(autoRiskNum) === \'CRIT\') {\n      if (sub) sub.textContent = `CRIT risk (${autoRiskNum}) — auto-escalating to Executive Portal…`;\n      nodeEl.textContent = `Threshold breach (CRIT, ${autoRiskNum}) — auto-escalating…`;\n      setTimeout(() => escalateToExecutive(), 1200);\n    }\n \n  } catch(e) {\n    // Same graceful-degradation pattern as the BPO/insurance/mortgage\n    // strategists: a transient Groq failure (rate limit, timeout, aborted\n    // stream) should never dead-end the escalate path. Without this, a 429\n    // here writes a short "[Groq Error] ..." string into #bncaOutput, which\n    // trips escalateToExecutive()\'s `bncaText.length < 50` guard — firing a\n    // blocking alert() and silently no-oping the click instead of navigating.\n    console.warn(\'[construction-strategist] BNCA synthesis failed, using fallback brief:\', e.message);\n    const fallback = buildConstructionBNCAFallback(warRoomRelay, e.message);\n    out.textContent = fallback;\n    const {brief: conBrief, obj: conObj} = conXPParseExplain(fallback);\n    if (conBrief) out.textContent = conBrief;\n    conXPRenderExplain(conObj);\n    lastConObj = conObj;\n    out.classList.remove(\'streaming\');\n    nodeEl.textContent = `BNCA fallback — live synthesis unavailable · ${new Date().toLocaleTimeString()}`;\n    storeStrategistRelay(fallback, conObj);\n    const sub = document.getElementById(\'escalBarSub\');\n    if (sub) sub.textContent = \'BNCA fallback generated — ready to escalate to Executive Portal.\';\n  } finally {\n    clearTimeout(streamTimeoutId);\n  }\n}\n\n// ── FALLBACK BNCA BRIEF ──\n// Used only when the live /api/war-room/stream call fails. Built from real\n// warRoomRelay fields (docType, risk, exposure) — never invents numbers —\n// same honesty convention as bpo\'s buildStrategyFallback / insurance\'s\n// NODE_FALLBACKS.\nfunction buildConstructionBNCAFallback(relay, errMsg) {\n  const snap = relay?.snapshot || {};\n  const docType = relay?.docType || \'Construction matter\';\n  const risk = snap.risk || \'Unclassified\';\n  const exposure = snap.exposure || \'Unconfirmed — see engine outputs\';\n  return `CONTROLLER PRIORITY ACTIONS\n1. Live BNCA synthesis unavailable (${errMsg}) — re-run "Synthesize All" once the engine is available for a fully synthesized brief. Owner: Strategist\n2. Escalate now on the War Room engine findings already on record rather than waiting — exposure data is real, only this synthesis step degraded. Owner: Principal\n3. Flag this run as fallback-generated in any downstream reporting. Owner: Compliance Officer\n\nAPP ROUTING GUIDANCE\nRoute to the relevant Construction Suite app (AuditOps, Financial, Legal, or Compliance) based on the War Room\'s own engine flags for ${docType} — this fallback does not re-derive routing.\n\nBNCA — BEST NEXT COURSE OF ACTION\nAct on the War Room\'s already-captured risk (${risk}) and exposure (${exposure}) for ${docType} within the next 72 hours; regenerate this brief live once the engine is reachable.\n\nESCALATION TRIGGER\nLive engine remains unavailable beyond this session.\n\n===JSON===\n{"confidence":50,"dataSources":[{"name":"War Room engine snapshot","weight":"HIGH"},{"name":"Live BNCA synthesis","weight":"LOW"}],"reasoning":[{"key":"Fallback reason","val":"${errMsg}"},{"key":"Data integrity","val":"Engine outputs are real and unaffected; only the synthesis step failed"}],"recommendedActions":[{"text":"Re-run synthesis once live engine available","owner":"Strategist"},{"text":"Escalate on engine findings now","owner":"Principal"}],"noActionRevLoss":"${exposure}","actionRevLoss":"Unconfirmed pending live synthesis","recoveryTime":"Unconfirmed pending live synthesis"}`;\n}\n '
old_inject = "    window.assignConstIssuePack = function(role){\n      const content=document.getElementById('cip-output')?.textContent||'';\n      if(!content){alert('Run the issue pack first.');return;}\n      const queue=JSON.parse(localStorage.getItem('tsm_const_issue_queue')||'[]');\n      queue.push({role,assignedAt:new Date().toLocaleString(),docType:brief.docType,exposure:brief.snapshot?.exposure,packSnippet:content.slice(0,300)});\n      localStorage.setItem('tsm_const_issue_queue',JSON.stringify(queue));\n      const tag=document.getElementById('cip-assign-tag');\n      if(tag){tag.style.display='block';tag.textContent='✓ ASSIGNED TO: '+role.toUpperCase()+' · '+new Date().toLocaleTimeString();}\n    };\n\n  } catch(e){ console.warn('Construction issue pack error:',e); }\n})();"
new_inject = '    window.assignConstIssuePack = function(role){\n      const content=document.getElementById(\'cip-output\')?.textContent||\'\';\n      if(!content){alert(\'Run the issue pack first.\');return;}\n      const queue=JSON.parse(localStorage.getItem(\'tsm_const_issue_queue\')||\'[]\');\n      queue.push({role,assignedAt:new Date().toLocaleString(),docType:brief.docType,exposure:brief.snapshot?.exposure,packSnippet:content.slice(0,300)});\n      localStorage.setItem(\'tsm_const_issue_queue\',JSON.stringify(queue));\n      const tag=document.getElementById(\'cip-assign-tag\');\n      if(tag){tag.style.display=\'block\';tag.textContent=\'✓ ASSIGNED TO: \'+role.toUpperCase()+\' · \'+new Date().toLocaleTimeString();}\n    };\n\n    // "◈ INJECT INTO STRATEGIST" button — was calling a function that was\n    // never defined anywhere in this file (dead onclick, guaranteed\n    // ReferenceError on click). This brief is already parsed in scope, so\n    // inject it as the active war room relay and immediately (re)run the\n    // main BNCA synthesis on it — same effect loadWarRoomRelay() has on\n    // page load, just explicit and on-demand instead of the 1000ms auto-timer.\n    window.injectWarRoomContext = function(){\n      warRoomRelay = brief;\n      populateFromWarRoom(brief);\n      if (typeof runConstructionBNCAFromRelay === \'function\') runConstructionBNCAFromRelay();\n    };\n\n  } catch(e){ console.warn(\'Construction issue pack error:\',e); }\n})();'

c1 = content.count(old_func)
assert c1 == 1, f"expected exactly 1 match for the BNCA function block, found {c1} — file may have diverged, check manually"
content = content.replace(old_func, new_func, 1)

c2 = content.count(old_inject)
assert c2 == 1, f"expected exactly 1 match for the inject-button block, found {c2} — file may have diverged, check manually"
content = content.replace(old_inject, new_inject, 1)

with open(path, "w") as fh:
    fh.write(content)
print(f"Patched {path}: (1) added fallback+abort-timeout to runConstructionBNCAFromRelay, (2) defined injectWarRoomContext")

PYEOF_INNER

python3 /tmp/_construction_patch.py "$FILE"
